import React from "react";
import { Button } from "@mui/material";

const AutomationControl = () => {
  return (
    <div className="flex justify-center my-8">
      <Button variant="contained" color="secondary">
        Start Automation
      </Button>
    </div>
  );
};

export default AutomationControl;
